import {jointAxisNames} from './joint-dofs.js';
export function jointDOFControls(rows,attrs,esc,{disabled=false}={}){const off=disabled?' disabled':'';return '<div class="joint-dofs">'+rows.map((row,index)=>{const attr=field=>attrs+' data-joint-dof-index="'+index+'" data-joint-dof-field="'+field+'"',number=(key,label)=>'<div class="component-property"><label>'+label+'</label><input type="number" step="any" value="'+esc(row[key])+'" '+attr(key)+' aria-label="'+jointAxisNames[index]+' '+label+'"'+off+'></div>';return '<details><summary>'+jointAxisNames[index]+' · '+(index<3?'m':'도')+'</summary><div class="component-property"><label>운동</label><select '+attr('mode')+' aria-label="'+jointAxisNames[index]+' 운동"'+off+'>'+[['locked','고정'],['limited','제한'],['free','자유']].map(([key,name])=>'<option value="'+key+'" '+(row.mode===key?'selected':'')+'>'+name+'</option>').join('')+'</select></div>'+(row.mode==='limited'?number('lower','최소')+number('upper','최대'):'')+'<div class="component-property"><label>모터</label><input type="checkbox" '+attr('motor')+(row.motor?' checked':'')+off+' aria-label="'+jointAxisNames[index]+' 모터"></div>'+(row.motor?number('position','목표 위치 / 각도')+number('velocity','목표 속도')+number('stiffness','강성')+number('damping','감쇠')+number('maxForce',index<3?'최대 힘 (N) · 0 무제한':'최대 토크 (N·m) · 0 무제한'):'')+'</details>';}).join('')+'</div>';}
